  ],
  "claims": [
    {
      "claim": "Transferable human L1/L2 absolute-bioavailability contexts are all above the 20% threshold: trazodone 63-91% (C43, C21), alprazolam 80-100% (C30, C07), netupitant 63-87% (C15, C39), triazolam 0.55 (C28), flibanserin 33-46% (C42, C06, C10), metolazone about 100% (C23), and tasquinimod excellent (C14).",
      "card_ids": ["C21","C07","C15","C28","C06","C10","C23","C14","C43","C30","C39","C42"]
    },
    {
      "claim": "New L3 oral-exposure records for structurally related N-aryl heterocycles show substantial oral Cmax/AUC: pirfenidone Cmax 7.9-17.1 µg/mL in humans (C50, C53, C61), trazodone capsule AUC 10.07 µg·h/mL (C56), and suxibuzone/oxyphenbutazone Cmax 5.0-6.7 µg/mL in horses (C60); these are consistent with favorable oral absorption and provide no affirmative F<20% signal.",
      "card_ids": ["C50","C53","C56","C60","C61"]
    },
    {
      "claim": "The only low absolute value, alprazolam in rat B at 4.5% (C32), is a single rodent observation that conflicts with consistent human alprazolam values of 80-100% (C30, C07) and is not transferable to the query; it does not provide affirmative evidence for F<20%.",
      "card_ids": ["C32","C30","C07"]
    },
    {
      "claim": "The selegiline record with oral/IV dose-normalized Cmax ratio 0.49 (C55) is structurally distant from the N-aryl pyrazolone query and does not constitute affirmative evidence for F<20%; no L3 record directly measures query bioavailability.",
      "card_ids": ["C55"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "oral_auc_cmax_exposure",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C50","C51","C52","C53","C54","C55","C56","C57","C58","C59","C60","C61"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement exists for the query molecule.",
    "L3 records are oral exposure (Cmax/AUC) for reference molecules, not F measurements for the query.",
    "First-pass metabolism and transporter effects for the query are not directly measured; selegiline C55 is too distant to quantify this risk.",
    "Some L3 records are non-human (horse/dog) and have limited transferability.",
    "No exact ChEMBL evidence was provided for the query."
  ],
  "decision_summary": "L3 oral-exposure records for structurally related N-aryl heterocycles (pirfenidone, trazodone, suxibuzone) show substantial oral Cmax/AUC and are consistent with the high prediction; no L3 record provides affirmative evidence for F<20%. The high prediction is strengthened with moderate confidence."
}

